import pytest
from wordfreq import count_words

def test_count_words_simple_sentence():
    text = 'Hello, world!'
    result = count_words(text)
    assert result == {'hello': 1, 'world': 1}

def test_count_words_punctuation():
    text = 'Hello, world! How are you?'
    result = count_words(text)
    assert result == {'hello': 1, 'world': 1, 'how': 1, 'are': 1, 'you': 1}

def test_count_words_case_insensitivity():
    text = 'Hello, World! hello, world!'
    result = count_words(text)
    assert result == {'hello': 2, 'world': 2}

