def count_words(text):
    import string
    translator = str.maketrans('', '', string.punctuation)
    text = text.translate(translator)
    words = text.lower().split()
    word_count = {}
    for word in words:
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1
    return word_count
